def solution(data: str) -> str:
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges_data = []
    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges_data.append((x, y, w, i + 1))

    def build_graph(excluded_indices: List[int]) -> List[List[List]]:
        graph = [[] for _ in range(n + 1)]
        for i in range(m):
            idx = edges_data[i][3] - 1
            if idx in excluded_indices:
                continue
            _, u, v, w = edges_data[i]
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def bfs(start: int, target: int, graph: List[List]) -> bool:
        if start == target:
            return True
        visited = [False] * (n + 1)
        queue = [start]
        visited[start] = True

        while queue:
            u = queue.pop(0)
            for v in graph[u]:
                if v == target:
                    return True
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Try 0 edges
    min_cost = float('inf')
    result_count = 0
    result_edges = []

    if not bfs(s, t, build_graph([])):
        return f"0\n0\n"

    # Try 1 edge
    for i in range(m):
        excluded = [i]
        if not bfs(s, t, build_graph(excluded)):
            cost = edges_data[i][2]
            if cost < min_cost:
                min_cost = cost
                result_count = 1
                result_edges = [edges_data[i][3]]
                if cost == 0:
                    break

    if result_count == 1 or result_count == 0:
        return f"{min_cost}\n{result_count}\n{' '.join(map(str, result_edges))}\n"

    # Try 2 edges
    for i in range(m):
        for j in range(i + 1, m):
            excluded = [i, j]
            if not bfs(s, t, build_graph(excluded)):
                cost = edges_data[i][2] + edges_data[j][2]
                if cost < min_cost:
                    min_cost = cost
                    result_count = result_edges = [edges_data[j][3]]

    return f"{min_cost}\n2\n{' '.join(map(str, result_edges))}\n"
