    friend_set = set()

    idx = 1
    current_block = set()

    while idx <= n:
        parts = data[idx].split()
        if parts[0] == '1':
            blocks.append(current_block)
            current_block = set()
        else:
            friend = parts[1]
            friend_set.add(friend)
            current_block.add(friend)
        idx += 1
    if current_block:
        blocks.append(current_block)

    friends = list(friend_set)
    n_friends = len(friends)

    conflict = [[False] * n_friends for _ in range(n_friends)]

    for block in blocks:
        names_in_block = list(block)
        idx_map = {name: i for i, name in enumerate(names_in_block)}
        k = len(names_in_block)
        if k <= 1:
            continue
        for i in range(k):
            for j in range(i + 1, k):
                conflict[idx_map[names_in_block[i]]][idx_map[names_in_block[j]]] = True
                conflict[idx_map[names_in_block[j]]][idx_map[names_in_block[i]]] = True

    # Maximum independent set using bitmask
    max_happy = 0
    for mask in range(1 << n_friends):
        valid = True
        for i in range(n_friends):
            if mask & (1 << i):
                for j in range(n_friends):
                    if i != j and (mask & (1 << j)) and conflict[i][j]:
                        valid = False
                        break
        if valid:
            max_happy = max(max_happy, bin(mask).count('1'))

    return str(max_happy)
