from math import isqrt

MOD = 10**9 + 7

def is_perfect_square(x):
    val = isqrt(x)
    return val * val == x

def get_square_free_part(n):
    result = 1
    d = 2
    while d * d <= n:
        while n % (d * d) == 0:
            n //= d * d
        if n % d == 0 and is_perfect_square(d):
            while n % d == 0:
                n //= d
                result *= d
        if d == 2:
            d = 3
        else:
            d += (2 if d == 3 else 1)
    if n > 1:
        result = (result * n) % MOD
    return result

def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res = (res * (i % MOD)) % MOD
    return res

def inverse(n):
    pow_n = pow(n, MOD - 2, MOD)
    return pow_n

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    square_free = [0] * 300
    for x in a:
        sf = get_square_free_part(x)
        square_free[sf] += 1

    counts = sorted([f for f in square_free if f > 0])

    if not counts:
        return "0"

    k = len(counts)

    fact = [1] * (k + 1)
    inv_fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD
        inv_fact[i] = inverse(fact[i])

    def C(n, m):
        if m < 0 or m > n:
            return 0
        return (fact[n] * inv_fact[m] * inv_fact[n - m]) % MOD

    def C_mod_w(n, m, w):
        return (fact[n] * inv_fact[m] * inv_fact[n - m] * pow(w, m, MOD)) % MOD

    def digit_dp():
        results = 0
        pre = 0
        for i in range(1, k + 1):
            cnt = counts[i - 1]
            comb = C(cnt, cnt)
            results = (results + comb) % MOD
            pre = (pre + comb) % MOD

        return results

    result = digit_dp()
    return str(result % MOD)

