def all_rectangles_equal(matrix, r, c):
    nr, nc = len(matrix), len(matrix[0])
    reference = None

    for i in range(0, nr, r):
        for j in range(0, nc, c):
            rect = extract_rect(matrix, i, j, r, c)
            if reference is None:
                reference = rect
            elif reference != rect:
                return False

    return True

def extract_rect(matrix, row, col, h, w):
    return [tuple(matrix[row + x][col + y] for y in range(w)) for x in range(h)]
